import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_ZIP_PLUS4_RE = re.compile(r"^\d{4,5}-\d{4}$")
_DIGITS = frozenset("0123456789")


def _norm_email(raw):
    s = raw.strip()
    if "<" in s:
        start = s.index("<")
        end = s.find(">", start + 1)
        if end != -1:
            s = s[start + 1:end]
    s = s.strip().lower()
    local, sep, domain = s.partition("@")
    if sep and domain in _GMAIL_DOMAINS:
        local = local.replace(".", "")
        local = local.split("+", 1)[0]
        s = local + "@gmail.com"
    return s


def _valid_email(e):
    if e.count("@") != 1:
        return False
    local, domain = e.split("@")
    return (bool(local) and "." in domain
            and not domain.startswith(".") and not domain.endswith("."))


def _norm_phone(raw):
    s = raw.lower()
    cut = len(s)
    for marker in ("ext", "x", "#"):
        i = s.find(marker)
        if i != -1 and i < cut:
            cut = i
    digits = "".join(c for c in s[:cut] if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _norm_zip(raw):
    z = raw.strip()
    if _ZIP_PLUS4_RE.match(z):
        z = z.split("-", 1)[0]
    if len(z) == 4 and all(c in _DIGITS for c in z):
        z = "0" + z
    if len(z) == 5 and all(c in _DIGITS for c in z):
        return z
    return ""


def _norm_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _pick(group, field):
    """Pick the normalized value of `field` from the group.

    Candidates are rows where the normalized field is non-empty. Rows with
    source "manual" are preferred; among those, the latest `updated` wins.
    max() returns the first maximal element, so ties go to the earlier row.
    """
    cands = [r for r in group if r[field]]
    if not cands:
        return ""
    manual = [r for r in cands if r["source"] == "manual"]
    pool = manual or cands
    return max(pool, key=lambda r: r["updated"])[field]


def dedupe_contacts(rows):
    # Step 1: normalize rows and drop those without a valid email or phone.
    recs = []
    for idx, row in enumerate(rows):
        email = _norm_email(row.get("email", ""))
        if not _valid_email(email):
            email = ""
        phone = _norm_phone(row.get("phone", ""))
        if not email and not phone:
            continue
        tags = {t.strip().lower() for t in re.split(r"[;,]", row.get("tags", ""))}
        tags.discard("")
        recs.append({
            "index": idx,
            "first_name": _norm_name(row.get("first_name", "")),
            "last_name": _norm_name(row.get("last_name", "")),
            "zip": _norm_zip(row.get("zip", "")),
            "email": email,
            "phone": phone,
            "source": row.get("source", "").strip().lower(),
            "tags": tags,
            "opted_out": row.get("opted_out", "").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row.get("updated", "")),
        })

    # Step 2: union-find. Rows match on a shared valid email, or on a shared
    # valid phone plus the same non-empty last name (case-insensitive).
    parent = list(range(len(recs)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    email_seen = {}
    phone_seen = {}
    for pos, r in enumerate(recs):
        if r["email"]:
            if r["email"] in email_seen:
                union(pos, email_seen[r["email"]])
            else:
                email_seen[r["email"]] = pos
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].casefold())
            if key in phone_seen:
                union(pos, phone_seen[key])
            else:
                phone_seen[key] = pos

    # Group members, ordered by the earliest row of each group.
    groups = {}
    order = []
    for pos in range(len(recs)):
        root = find(pos)
        if root not in groups:
            groups[root] = []
            order.append(root)
        groups[root].append(recs[pos])

    # Step 3: build one output record per person.
    result = []
    for root in order:
        g = groups[root]
        tags = sorted(set().union(*(r["tags"] for r in g)))
        result.append({
            "first_name": _pick(g, "first_name"),
            "last_name": _pick(g, "last_name"),
            "zip": _pick(g, "zip"),
            "email": _pick(g, "email"),
            "phone": _pick(g, "phone"),
            "source": _pick(g, "source"),
            "tags": ";".join(tags),
            "opted_out": "Y" if any(r["opted_out"] for r in g) else "N",
            "updated": max(r["updated"] for r in g).strftime("%Y-%m-%d"),
        })
    return result
```

Notes:

- **Opt-outs:** `dedupe_contacts` doesn't drop opted-out people; it marks them `opted_out == "Y"`. Filter on that before sending, e.g. `[p for p in dedupe_contacts(rows) if p["opted_out"] == "N"]`. Because a person is merged across duplicate rows, one opt-out on any duplicate excludes that person entirely, which is the conservative choice for this send.
- **ZIP+4 interpretation:** I treated the ZIP+4 pattern as a 4- or 5-digit prefix followed by a 4-digit suffix, so Excel-mangled prefixes like `2139-4307` still get the leading zero. If you want only exact 5-digit prefixes, change the regex to `^\d{5}-\d{4}$`.
- **Bad dates:** An `updated` value outside the three formats raises `ValueError` rather than being silently sorted as oldest. Better to fix the export than guess which record is newest.

